    root.addEventListener("input", (event) => { const row = event.target.closest("[data-decision-line]"); if (row) { syncReasonPanel(row); validateRows(true); } });
    root.addEventListener("change", (event) => { const row = event.target.closest("[data-decision-line]"); if (row) { syncReasonPanel(row); validateRows(true); } });
