      const order = orders.find((item) => item.id === selected); const now = new Date(); const version = "SIAL-MAT-1.0";
      const content = [`VERSION|PEDIDO|ORIGEN|USUARIO|FECHA|RESULTADO`, `${version}|${order.id}|SIAL|QA Materiales|${now.toISOString()}|SOLICITUD_CONSULTA`].join("\r\n");
